RUN=BASE/'runs/20261112-blind-theory-01'
esc=lambda s:html.escape(str(s))
def read(name):return json.loads((RUN/name).read_text())
def link(path,label,line=1):return f'<a href="vscode://file{esc(str(Path(path).resolve()))}:{line}">{esc(label)}</a>'
def source(name,label):return link(RUN/name,label)
def span_seconds(rows):
    stamp=lambda s:datetime.fromisoformat(s.replace('Z','+00:00'))
    return (max(stamp(x['ended_at']) for x in rows)-min(stamp(x['started_at']) for x in rows)).total_seconds()
def result_label(row):
    if row['exact']:return '<span class="badge found">Exact target</span>'
    if row['fault_found']:return '<span class="badge related">Related finding</span>'
    return '<span class="badge miss">Not reported</span>'

