css=re.search(r'<style>(.*?)</style>',(ROOT/'.lavish/agent-baseline.html').read_text(),re.S)[1]
css+='''\n.related{color:var(--purple);background:var(--code)}.metricbar{display:flex;height:20px;border-radius:4px;overflow:hidden;background:var(--border);margin:8px 0 18px}.metricbar .exact{background:var(--cyan)}.metricbar .related-fill{background:#a997d9}.flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.flow>div{border:1px solid var(--border);border-radius:9px;background:var(--panel);padding:15px;min-width:0}.flow b{display:block}.flow span{font-size:14px;color:var(--muted)}.proof-chain{padding:18px;border:1px solid var(--border);border-radius:10px;background:var(--panel)}.proof-chain div{padding:12px;border-left:4px solid var(--cyan);margin:9px 0}.proof-chain .failed{border-color:var(--rose);background:var(--code)}.log{font-family:SFMono-Regular,Consolas,monospace;font-size:14px;white-space:pre-wrap;overflow-wrap:anywhere;background:var(--code);padding:16px;border-radius:8px}.case-detail td{background:var(--code)}.case-detail .cards{margin:8px 0}.case-detail p{font-size:14px}.case-detail h4{margin:6px 0}.case-detail[hidden]{display:none}#case-table{min-width:720px}.large-number{font-size:27px;font-weight:700}.sensitivity{border-left-color:var(--amber)}.footnote{color:var(--muted);font-size:14px}@media(max-width:850px){.flow{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:450px){.flow{grid-template-columns:1fr}}'''

